const match=/^K-([0-9]+)-([0-6])$/.exec(row.number || "");
if (!match) return {error:"CHECKSUM_FORMAT"};
const n=Number(match[1]);
if (!Number.isSafeInteger(n) || n%7!==Number(match[2]))
  return {error:"CHECKSUM_MISMATCH"};
return {checksum_valid:true};
